input.command:
cd ~/.claude/projects && d=$(dirname $(find . -name "b046f754-91e1-4663-9cd7-ce287d366b60.jsonl" | head -1)); echo $d; ls $d | head; python3 - "$d" <<'EOF'
import json,sys,glob,collections,os
d=sys.argv[1]
c=collections.Counter(); keys=collections.defaultdict(set)
files=glob.glob(os.path.join(d,'*.jsonl'))[:40]+glob.glob(os.path.join(d,'*/subagents/*.jsonl'))[:40]
for f in files:
  for l in open(f):
    try: r=json.loads(l)
    except: c['BAD']+=1; continue
    t=r.get('type'); c[t]+=1; keys[t]|=set(r.keys())
print(len(files)); print(c.most_common())
for t in ('user','assistant','system','cost-state'): print(t, sorted(keys[t]))
m=glob.glob(os.path.join(d,'*/subagents/*.meta.json'))
print(len(m)); 
if m: print(open(m[0]).read()[:400])
EOF
claude --version

